#!/usr/bin/env bash
################################################################################
# barr_check.sh -- BARR-C:2018 checks that a script can do reliably.
#
# Usage (from anywhere inside the repo):   tools/barr_check.sh
# Exit code: 0 = no findings, 1 = at least one finding.
# Output:    one line per finding, "file:line: rule: text".
#
# Scans app_program/**/*.c and *.h, except:
#   *.pio.h          generated by pioasm (third-party)
#   app_layout.h     generated by tools/gen_layout.py
#   test_report.h    course template file, kept unchanged (Part B.5)
#
# Checks (rule numbers from the BARR-C:2018 standard / team spec Part C):
#   3.5.a  tab characters             1.2.a  lines longer than 80 characters
#   5.4.a  float / double             8.4.c  while (1) instead of for (;;)
#   1.7    goto, continue, register, auto
#   3.3.c  last non-empty line is not "/*** end of file ***/"
#   4.2.a  a .c file without a .h of the same root
#   4.1.b  two module names whose first 8 characters are equal
#   proj   printf( / tm_printf( outside app_main.c (use app_log)
#   1.1.c  __attribute__
#   proj   a C bit-field declaration inside a struct
#
# Owner: Team (integrator).  Run before every push (Part C.6).
################################################################################

set -u

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
APP_DIR="${ROOT}/app_program"
FINDINGS=0

# report <file> <rule> <text>  -- lines come from "grep -n" ("line:text")
report() {
    local file="$1"
    local rule="$2"
    local line
    while IFS= read -r line; do
        [ -z "${line}" ] && continue
        printf '%s:%s: %s: %s\n' "${file#"${ROOT}"/}" "${line%%:*}" \
            "${rule}" "${line#*:}"
        FINDINGS=$((FINDINGS + 1))
    done
}

# One finding without a line number from grep.
report_one() {
    printf '%s:%s: %s: %s\n' "${1#"${ROOT}"/}" "$2" "$3" "$4"
    FINDINGS=$((FINDINGS + 1))
}

mapfile -t FILES < <(find "${APP_DIR}" -type f \( -name '*.c' -o -name '*.h' \) \
    ! -name '*.pio.h' ! -name 'app_layout.h' ! -name 'test_report.h' \
    | sort)

for f in "${FILES[@]}"; do
    # Strip a Windows CR so CRLF checkouts are judged on content only.
    content="$(tr -d '\r' < "${f}")"
    # Keyword checks look at code only: blank out comments and string
    # literals but keep every newline, so line numbers stay correct.
    code="$(perl -0777 -pe \
        's{/\*.*?\*/}{(my $c = $&) =~ s/[^\n]//g; $c}gse;
         s{"(?:\\.|[^"\\\n])*"}{""}g' <<< "${content}")"

    report "${f}" "3.5.a" < <(grep -nP '\t' <<< "${content}" \
        | sed 's/\t/<TAB>/g')
    report "${f}" "1.2.a" < <(awk 'length($0) > 80 \
        { printf "%d:line is %d characters\n", NR, length($0) }' \
        <<< "${content}")
    report "${f}" "5.4.a" < <(grep -nwE 'float|double' <<< "${code}")
    report "${f}" "8.4.c" < <(grep -nE 'while[[:space:]]*\([[:space:]]*1[[:space:]]*\)' \
        <<< "${code}")
    report "${f}" "1.7" < <(grep -nwE 'goto|continue|register' \
        <<< "${code}")
    report "${f}" "1.7" < <(grep -nE '(^|[^[:alnum:]_])auto[[:space:]]' \
        <<< "${code}")
    report "${f}" "1.1.c" < <(grep -nF '__attribute__' <<< "${code}")
    report "${f}" "bit-field" < <(grep -nE \
        '^\s*(unsigned|signed|int|uint\w*|bool)\s+\w+\s*:\s*[0-9]+\s*;' \
        <<< "${code}")

    if [ "$(basename "${f}")" != "app_main.c" ]; then
        report "${f}" "printf" < <(grep -nE \
            '(^|[^[:alnum:]_])(tm_)?printf[[:space:]]*\(' <<< "${code}")
    fi

    last="$(grep -n -v '^[[:space:]]*$' <<< "${content}" | tail -n 1)"
    if [ "${last#*:}" != "/*** end of file ***/" ]; then
        report_one "${f}" "${last%%:*}" "3.3.c" \
            "last non-empty line is not /*** end of file ***/"
    fi

    case "${f}" in
        *.c)
            if [ ! -f "${f%.c}.h" ]; then
                report_one "${f}" "1" "4.2.a" "no .h file with the same root name"
            fi
            ;;
        *)
            ;;
    esac
done

# 4.1.b: module = file name without .c/.h; first 8 characters must differ.
declare -A PREFIX_OWNER=()
while IFS= read -r module; do
    key="${module:0:8}"
    if [ -n "${PREFIX_OWNER[${key}]+set}" ] \
        && [ "${PREFIX_OWNER[${key}]}" != "${module}" ]; then
        report_one "app_program/${module}" "1" "4.1.b" \
            "first 8 characters equal to module ${PREFIX_OWNER[${key}]}"
    else
        PREFIX_OWNER[${key}]="${module}"
    fi
done < <(for f in "${FILES[@]}"; do
             b="${f##*/}"
             printf '%s\n' "${b%.*}"
         done | sort -u)

if [ "${FINDINGS}" -ne 0 ]; then
    printf 'barr_check: %d finding(s)\n' "${FINDINGS}"
    exit 1
fi

printf 'barr_check: %d files, no findings\n' "${#FILES[@]}"
exit 0
